{"metric_ids": ["repeat_customer"], "sql": "SELECT COUNT(*) AS repeat_customers FROM (
  SELECT c.customer_unique_id
  FROM orders o JOIN customers c ON c.customer_id = o.customer_id
  WHERE substr(o.order_purchase_timestamp, 1, 4) = '2017'
  GROUP BY c.customer_unique_id
  HAVING {{repeat_customer}}
)", "assumptions": []}

{"metric_ids": ["repeat_customer"], "sql": "SELECT ROUND(100.0 * SUM(is_repeat) / COUNT(*), 2) AS repeat_pct FROM (
  SELECT c.customer_unique_id, {{repeat_customer}} AS is_repeat
  FROM orders o JOIN customers c ON c.customer_id = o.customer_id
  GROUP BY c.customer_unique_id
)", "assumptions": ["Every order in the data counts, whatever its status."]}

{"metric_ids": ["active_seller"], "sql": "SELECT COUNT(*) AS sellers FROM (
  SELECT i.seller_id
  FROM order_items i JOIN orders o ON o.order_id = i.order_id
  WHERE substr(o.order_purchase_timestamp, 1, 4) = '2018'
  GROUP BY i.seller_id
  HAVING {{active_seller}}
)", "assumptions": []}

{"metric_ids": [], "sql": "SELECT ROUND(AVG(paid), 2) AS avg_order_value FROM (
  SELECT o.order_id, SUM(p.payment_value) AS paid
  FROM orders o JOIN order_payments p ON p.order_id = o.order_id
  WHERE substr(o.order_purchase_timestamp, 1, 4) = '2017'
  GROUP BY o.order_id
)", "assumptions": ["Order value is the sum of an order's payments; each order counts once."]}
